import { ConfigurationService } from '@ghostfolio/api/services/configuration/configuration.service';
import {
  DataProviderInterface,
  GetAssetProfileParams,
  GetDividendsParams,
  GetHistoricalParams,
  GetQuotesParams,
  GetSearchParams
} from '@ghostfolio/api/services/data-provider/interfaces/data-provider.interface';
import { DEFAULT_CURRENCY } from '@ghostfolio/common/config';
import { DATE_FORMAT } from '@ghostfolio/common/helper';
import {
  DataProviderHistoricalResponse,
  DataProviderInfo,
  DataProviderResponse,
  LookupResponse
} from '@ghostfolio/common/interfaces';

import { Injectable, OnModuleInit } from '@nestjs/common';
import { DataSource, SymbolProfile } from '@prisma/client';
import Alphavantage from 'alphavantage';
import { format, isAfter, isBefore, parse } from 'date-fns';

import { AlphaVantageHistoricalResponse } from './interfaces/interfaces';

@Injectable()
export class AlphaVantageService
  implements DataProviderInterface, OnModuleInit
{
  public alphaVantage;

  public constructor(
    private readonly configurationService: ConfigurationService
  ) {}

  public onModuleInit() {
    this.alphaVantage = Alphavantage({
      key: this.configurationService.get('API_KEY_ALPHA_VANTAGE')
    });
  }

  public canHandle() {
    return !!this.configurationService.get('API_KEY_ALPHA_VANTAGE');
  }

  public async getAssetProfile({
    symbol
  }: GetAssetProfileParams): Promise<Partial<SymbolProfile>> {
    return {
      symbol,
      dataSource: this.getName()
    };
  }

  public getDataProviderInfo(): DataProviderInfo {
    return {
      dataSource: DataSource.ALPHA_VANTAGE,
      isPremium: false,
      name: 'Alpha Vantage',
      url: 'https://www.alphavantage.co'
    };
  }

  public async getDividends({}: GetDividendsParams) {
    return {};
  }

  public async getHistorical({
    from,
    symbol,
    to
  }: GetHistoricalParams): Promise<{
    [symbol: string]: { [date: string]: DataProviderHistoricalResponse };
  }> {
    try {
      const historicalData: {
        [symbol: string]: AlphaVantageHistoricalResponse[];
      } = await this.alphaVantage.crypto.daily(
        symbol
          .substring(0, symbol.length - DEFAULT_CURRENCY.length)
          .toLowerCase(),
        'usd'
      );

      const response: {
        [symbol: string]: { [date: string]: DataProviderHistoricalResponse };
      } = {};

      response[symbol] = {};

      for (const [key, timeSeries] of Object.entries(
        historicalData['Time Series (Digital Currency Daily)']
      ).sort()) {
        if (
          isAfter(from, parse(key, DATE_FORMAT, new Date())) &&
          isBefore(to, parse(key, DATE_FORMAT, new Date()))
        ) {
          response[symbol][key] = {
            marketPrice: parseFloat(timeSeries['4a. close (USD)'])
          };
        }
      }

      return response;
    } catch (error) {
      throw new Error(
        `Could not get historical market data for ${symbol} (${this.getName()}) from ${format(
          from,
          DATE_FORMAT
        )} to ${format(to, DATE_FORMAT)}: [${error.name}] ${error.message}`
      );
    }
  }

  public getName(): DataSource {
    return DataSource.ALPHA_VANTAGE;
  }

  public async getQuotes({}: GetQuotesParams): Promise<{
    [symbol: string]: DataProviderResponse;
  }> {
    return {};
  }

  public getTestSymbol() {
    return undefined;
  }

  public async search({ query }: GetSearchParams): Promise<LookupResponse> {
    const result = await this.alphaVantage.data.search(query);

    return {
      items: result?.bestMatches?.map((bestMatch) => {
        return {
          assetClass: undefined,
          assetSubClass: undefined,
          currency: bestMatch['8. currency'],
          dataProviderInfo: this.getDataProviderInfo(),
          dataSource: this.getName(),
          name: bestMatch['2. name'],
          symbol: bestMatch['1. symbol']
        };
      })
    };
  }
}

